using System.Windows;using System.Windows.Controls;using LibraryManager.Services;using LibraryManager.Models;namespace LibraryManager.Views;public partial class MembersView:UserControl{MemberService svc=new();DataGrid grid;public MembersView(){InitializeComponent();var p=VH.Page(Root,"اعضا");var q=VH.Input(p,"جست‌وجو با نام یا کد ملی");grid=VH.Table(p,svc.All());q.TextChanged+=(s,e)=>grid.ItemsSource=svc.All().Where(x=>(x.FirstName+x.LastName+x.NationalId).Contains(q.Text)).ToList();p.Children.Add(VH.Btn("عضو جدید",(s,e)=>{var w=new AddMemberWindow();if(w.ShowDialog()==true)Refresh();}));p.Children.Add(VH.Btn("تمدید عضویت",(s,e)=>{if(grid.SelectedItem is Member m&&PaymentDialog.ShowPayment("تمدید عضویت")){try{svc.Renew(m.Id,12,PaymentDialog.Method);Refresh();}catch(Exception ex){VH.Error(ex);}}}));p.Children.Add(VH.Btn("حذف",(s,e)=>{try{if(grid.SelectedItem is Member m)svc.Delete(m.Id);Refresh();}catch(Exception ex){VH.Error(ex);}}));}void Refresh()=>grid.ItemsSource=svc.All();}